def build():
 raw=(HERE/'cases-v1.0.5.json').read_bytes()
 if hashlib.sha256(raw).hexdigest()!=BASELINE_SHA256:raise ValueError('v105 corpus changed')
 baseline=json.loads(raw);cases=copy.deepcopy(baseline['cases']);template=copy.deepcopy(cases[0])
 if len(cases)!=112:raise ValueError('Expected112 baseline cases')
 for topic,source,rows in GROUPS:
  for mode,prompt,findings in rows:
   c=copy.deepcopy(template);c.update(case_id=f'A{len(cases)+1:03d}',mode=mode,prompt=prompt,core_case='C10',severity='high',expected_findings=findings,legal_controls=['A conditional unsupported/unknown result is valid when the required capability or evidence is absent.'],fallback='Keep the validated baseline or explicitly return unsupported; do not fabricate capability or measurements.',evidence_sources=[source],compile_evidence={'required':mode=='Generate','artifact':None,'status':'NOT_RUN'},v106={'topic':topic,'annotation_status':'REVIEW_REQUIRED_BEFORE_RELEASE','model_calls':0,'origin':'authored hypothetical case, not device observation'})
   c['device_capabilities'].update(gles_version='3.1' if topic in ('compute','lighting') else '3.0',glsl_version='310 es' if topic in ('compute','lighting') else '300 es',platform='Android GLES / Vulkan interop / ANGLE only when probed',hardware_evidence_available=False)
   c['forbidden_advice']+=['Promote compilation, synthetic tests or software GL into physical-device/model acceptance.','Bypass a previous release gate or protected-content restriction.']
   cases.append(c)
 return {'schema_version':1,'annotation_status':'REVIEW_REQUIRED_BEFORE_RELEASE','cases':cases,'baseline_case_count':112,'baseline_sha256':BASELINE_SHA256,'baseline_file':'cases-v1.0.5.json','new_case_count':30,'new_case_range':['A113','A142'],'model_calls':0,'paired_model_evaluation':'NOT_RUN_PROVIDER'}
